from flask import Flask, request, session, jsonify, redirect, render_template_string
import sqlite3
import os
import hashlib
import time

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-secret-key-change-me')

DB_PATH = os.environ.get('DB_PATH', '/tmp/inventory.db')

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    db = get_db()
    db.executescript('''
        CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, role TEXT, email TEXT);
        CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, action TEXT, user_id INTEGER, ts REAL);
        CREATE TABLE IF NOT EXISTS inventory (id INTEGER PRIMARY KEY, sku TEXT, name TEXT, qty INTEGER, warehouse TEXT);
        INSERT OR IGNORE INTO users VALUES (1, 'admin', 'admin', 'admin@corp.local');
        INSERT OR IGNORE INTO users VALUES (2, 'operator', 'viewer', 'op@corp.local');
    ''')
    db.commit()

@app.before_request
def require_auth():
    public = ['/login', '/healthz', '/static']
    if any(request.path.startswith(p) for p in public):
        return None
    if 'user_id' not in session:
        return redirect('/login')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
        if user:
            session['user_id'] = user['id']
            session['role'] = user['role']
            return redirect('/dashboard')
    return render_template_string('<form method=post><input name=username><button>Login</button></form>')

@app.route('/dashboard')
def dashboard():
    return render_template_string('''<h1>Dashboard</h1>
        <a href="/api/inventory">Inventory</a> | 
        <a href="/api/users">Users</a>''')

@app.route('/api/inventory', methods=['GET'])
def list_inventory():
    db = get_db()
    warehouse = request.args.get('warehouse', '%')
    # Parameterized query - safe
    items = db.execute('SELECT * FROM inventory WHERE warehouse LIKE ?', (warehouse,)).fetchall()
    return jsonify([dict(i) for i in items])

@app.route('/api/inventory/adjust', methods=['POST'])
def adjust_inventory():
    """Adjust inventory quantity - requires operator or admin role"""
    if session.get('role') not in ('admin', 'operator'):
        return jsonify({'error': 'forbidden'}), 403
    data = request.form if request.content_type == 'application/x-www-form-urlencoded' else request.get_json(force=True)
    sku = data.get('sku') if isinstance(data, dict) else data.get('sku')
    delta = int(data.get('delta', 0)) if isinstance(data, dict) else int(data.get('delta', 0))
    db = get_db()
    db.execute('UPDATE inventory SET qty = qty + ? WHERE sku = ?', (delta, sku))
    db.execute('INSERT INTO audit_log (action, user_id, ts) VALUES (?, ?, ?)',
               (f'adjust:{sku}:{delta}', session['user_id'], time.time()))
    db.commit()
    return jsonify({'status': 'adjusted', 'sku': sku, 'delta': delta})

@app.route('/api/users/<int:uid>/role', methods=['POST'])
def change_role(uid):
    """Change user role - admin only"""
    if session.get('role') != 'admin':
        return jsonify({'error': 'forbidden'}), 403
    new_role = request.form.get('role', 'viewer')
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (new_role, uid))
    db.execute('INSERT INTO audit_log (action, user_id, ts) VALUES (?, ?, ?)',
               (f'role_change:{uid}:{new_role}', session['user_id'], time.time()))
    db.commit()
    return jsonify({'status': 'updated', 'user_id': uid, 'new_role': new_role})

@app.route('/api/users', methods=['GET'])
def list_users():
    db = get_db()
    users = db.execute('SELECT id, username, role, email FROM users').fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/api/export', methods=['GET'])
def export_data():
    """Export inventory data - supports callback for legacy integrations"""
    callback = request.args.get('callback')
    db = get_db()
    items = db.execute('SELECT * FROM inventory').fetchall()
    data = str([dict(i) for i in items])
    if callback and callback.isalnum():
        return f'{callback}({data})', 200, {'Content-Type': 'application/javascript'}
    return jsonify([dict(i) for i in items])

@app.route('/healthz')
def health():
    return 'ok'

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=5000, debug=False)
